files.content:
.modal{
  width:calc(100% - var(--s-8));
  max-width:var(--w-modal);
  max-height:calc(100vh - var(--s-8));
  overflow:auto;
  margin:auto;
  padding:var(--s-6);
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  box-shadow:var(--sh-4);
  font-family:var(--font-sans);
  opacity:0;
  transform:translateY(var(--s-2));
  transition:opacity var(--d-quick) var(--ease-accel),transform var(--d-quick) var(--ease-accel), overlay var(--d-quick) var(--ease-accel) allow-discrete,display var(--d-quick) var(--ease-accel) allow-discrete;
}
.modal-wide{
  max-width:720px;
}
.modal[open]{
  opacity:1;
  transform:none;
  transition:opacity var(--d-quick) var(--ease-decel),transform var(--d-base) var(--ease-decel), overlay var(--d-quick) var(--ease-decel) allow-discrete,display var(--d-quick) var(--ease-decel) allow-discrete;
}
.modal::backdrop{
  background:transparent;
  transition:background var(--d-quick) var(--ease-accel),overlay var(--d-quick) var(--ease-accel) allow-discrete,display var(--d-quick) var(--ease-accel) allow-discrete;
}
.modal[open]::backdrop{
  background:var(--scrim);
  backdrop-filter:blur(var(--blur-veil));
  transition:background var(--d-quick) var(--ease-decel),overlay var(--d-quick) var(--ease-decel) allow-discrete,display var(--d-quick) var(--ease-decel) allow-discrete;
}
.modal-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--s-4);
  margin-bottom:var(--s-4);
}
.modal-title{
  margin:0;
  font-size:var(--t-h6);
  font-weight:700;
  line-height:var(--lh-snug);
}
.modal-body{
  margin:0;
  color:var(--obsidian-200);
  font-size:var(--t-body);
}
.modal-foot{
  display:flex;
  justify-content:flex-end;
  flex-wrap:wrap;
  gap:var(--s-2);
  margin-top:var(--s-6);
}
@media (prefers-reduced-motion:reduce){
  .modal, .modal[open]{
    transition:none;
    transform:none;
  }
  .modal::backdrop, .modal[open]::backdrop{
    transition:none;
  }
}
.modal{
  width:min(100%, calc(var(--s-32) * 2.5));
}
